const input = $input.first().json;
const candidateId = input.candidateId;
const jobId = input.jobId;
const backendUrl = $env.BOM_ECOM_URL || 'http://bom-ecom:5000';

return [{
  json: { candidateId, jobId, backendUrl }
}];

// Assemble the creative brief from all fetched data
const painPoints = $('Fetch Pain Points').first().json || [];
const phrases = $('Fetch Consumer Phrases').first().json || [];
const competitors = $('Fetch Competitor Messaging').first().json || [];
const candidate = $('Fetch Candidate Details').first().json || {};
const input = $('Parse Input').first().json;

// Top 20 pain points by emotional intensity
const topPains = (Array.isArray(painPoints) ? painPoints : [])
  .sort((a, b) => (b.emotionalIntensity || 0) - (a.emotionalIntensity || 0))
  .slice(0, 20)
  .map(p => ({
    painPointText: p.painPointText,
    rawQuotes: p.rawQuote ? [p.rawQuote] : [],
    emotionalIntensity: p.emotionalIntensity || 0,
    frequency: p.frequency || 1,
    painCategory: p.painCategory
  }));

// Top 30 phrases
const topPhrases = (Array.isArray(phrases) ? phrases : [])
  .slice(0, 30)
  .map(p => ({
    phrase: p.phrase,
    phraseType: p.phraseType,
    emotionalIntensity: p.emotionalIntensity || 0,
    useableAs: p.useableAs || []
  }));

// Competitor weaknesses
const competitorWeaknesses = (Array.isArray(competitors) ? competitors : [])
  .filter(c => c.weaknessIdentified)
  .map(c => ({
    brand: c.headline || 'Unknown',
    weakness: c.weaknessIdentified,
    rawQuotes: []
  }));

// Objections (pain points marked as objections)
const objections = (Array.isArray(painPoints) ? painPoints : [])
  .filter(p => p.painPointText && p.painPointText.startsWith('OBJECTION:'))
  .map(p => ({
    objection: p.painPointText.replace('OBJECTION: ', ''),
    rawQuotes: p.rawQuote ? [p.rawQuote] : [],
    counterArguments: []
  }));

const creativeBrief = {
  productName: candidate.name || 'Unknown Product',
  category: candidate.category || 'health',
  painPoints: topPains,
  consumerPhrases: topPhrases,
  objections,
  competitorWeaknesses,
  desiredOutcomes: []
};

return [{
  json: {
    ...input,
    creativeBrief,
    briefJson: JSON.stringify(creativeBrief)
  }
}];

