// Parse Vertex AI creative outputs
const vertexResponse = $input.first().json;
const input = $('Parse Input').first().json;

const text = vertexResponse?.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
let creative;
try {
  creative = JSON.parse(text);
} catch (e) {
  const match = text.match(/```json?\s*([\s\S]*?)```/);
  if (match) {
    creative = JSON.parse(match[1]);
  } else {
    creative = { taglines: [], hooks: [], pasFrameworks: [], beforeAfterStatements: [], objectionCrushers: [], mirrorPhrases: [] };
  }
}

const outputs = [];

// Map taglines
for (const t of (creative.taglines || [])) {
  outputs.push({
    outputType: 'tagline',
    content: t.content || t.tagline || t.text || '',
    targetEmotion: t.targetEmotion || null,
    persuasionPrinciple: t.persuasionPrinciple || null,
    awarenessLevel: t.awarenessLevel || null,
    qualityScore: 7
  });
}

// Map hooks
for (const h of (creative.hooks || [])) {
  outputs.push({
    outputType: 'hook',
    content: h.content || h.hook || h.text || '',
    contentStructured: { hookType: h.hookType, consumerPhraseUsed: h.consumerPhraseUsed },
    targetEmotion: h.targetEmotion || null,
    awarenessLevel: h.awarenessLevel || null,
    qualityScore: 7
  });
}

// Map PAS frameworks
for (const p of (creative.pasFrameworks || [])) {
  outputs.push({
    outputType: 'pas_framework',
    content: `Problem: ${p.problem || ''}\nAgitate: ${p.agitate || ''}\nSolve: ${p.solve || ''}`,
    contentStructured: { problem: p.problem, agitate: p.agitate, solve: p.solve },
    awarenessLevel: p.awarenessLevel || null,
    qualityScore: 7
  });
}

// Map before/after
for (const ba of (creative.beforeAfterStatements || [])) {
  outputs.push({
    outputType: 'before_after',
    content: `Before: ${ba.before || ''}\nAfter: ${ba.after || ''}`,
    contentStructured: { before: ba.before, after: ba.after, transformation: ba.transformation },
    qualityScore: 7
  });
}

// Map objection crushers
for (const oc of (creative.objectionCrushers || [])) {
  outputs.push({
    outputType: 'objection_crusher',
    content: oc.crusher || oc.content || '',
    contentStructured: { objection: oc.objection, mechanism: oc.mechanism },
    qualityScore: 7
  });
}

// Map mirror phrases
for (const mp of (creative.mirrorPhrases || [])) {
  outputs.push({
    outputType: 'mirror_phrase',
    content: mp.adAdaptation || mp.content || '',
    contentStructured: { consumerOriginal: mp.consumerOriginal, useCase: mp.useCase },
    targetEmotion: null,
    qualityScore: 7
  });
}

return [{
  json: {
    candidateId: input.candidateId,
    jobId: input.jobId,
    batchId: `batch-${Date.now()}`,
    outputs
  }
}];
